-- Elimina inferencias automáticas que la evidencia vigente no sostiene como funciones propias del actor Chile.
delete from public.aml_fintech_function_observation
where subject_type='ENTITY' and evidence_class='INFERRED_FROM_DECLARED' and (
  (subject_key='ENT-RUT-96637250-8' and function_code in ('FIN_LENDING','FIN_CARDS'))
  or (subject_key='ENT-RUT-77176962-4' and function_code='FIN_LENDING')
  or (subject_key='ENT-RUT-76893817-2' and function_code in ('FIN_LENDING','FIN_REGTECH','FIN_CARDS','VA_FIAT_EXCHANGE','VA_ON_OFF_RAMP','VA_STABLECOIN_SERVICES'))
  or (subject_key='ENT-RUT-77691219-0' and function_code in ('FIN_INVESTMENT','VA_FIAT_EXCHANGE'))
  or (subject_key='ENT-RUT-76113274-1' and function_code in ('FIN_LENDING','FIN_REGTECH'))
  or (subject_key='ENT-RUT-76704047-4' and function_code='FIN_REGTECH')
);

